+      frontier = fresh;
+    }
+    return out;
+  }
+
+  PosSet Reach(uint32_t id, const PosSet& in) {
+    const RxNode& node = p_.nodes[id];
+    PosSet out;
+    out.Init(n_ + 1);
+    switch (node.kind) {
+      case RxNode::Kind::kEmpty:
+        return in;
+      case RxNode::Kind::kAssert:
+        in.ForEach([&](size_t pos) {
+          if (node.assert_no_dot && pos < n_ && in_[pos] == '.') return;
