+ptrdiff_t IndexOf(PatternView str, char16_t c, ptrdiff_t from) {
+  if (from < 0) from = 0;
+  const size_t pos = str.find(c, static_cast<size_t>(from));
+  return pos == PatternView::npos ? kNone : static_cast<ptrdiff_t>(pos);
