+
+// /[-[\]{}()*+?.,\\^$|#\s]/, where \s is the whole JavaScript whitespace
+// set.
+bool NeedsRegExpEscape(char16_t c) {
+  switch (c) {
+    case u'-':
+    case u'[':
+    case u']':
+    case u'{':
+    case u'}':
+    case u'(':
+    case u')':
+    case u'*':
+    case u'+':
+    case u'?':
+    case u'.':
+    case u',':
+    case u'\\':
+    case u'^':
+    case u'$':
+    case u'|':
+    case u'#':
+    case u' ':
+    case u'\t':
+    case u'\n':
+    case u'\v':
+    case u'\f':
+    case u'\r':
+      return true;
+    default:
+      return c == 0x00A0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200A) ||
+             c == 0x202F || c == 0x205F || c == 0x3000 || c == 0xFEFF ||
+             IsLineTerminator(c);
+  }
