+  const withNulAb = withNulBuf.buffer.slice(
+    withNulBuf.byteOffset, withNulBuf.byteOffset + withNulBuf.byteLength);
+
+  const passphrases = [
+    withNul,
+    withNulBuf,
+    withNulAb,
+    new DataView(withNulAb),
+    new Uint8Array(withNulAb),
