+
+    if (!PyArg_ParseTuple(args, "O:pymarshal_read_short_from_file", &filename))
+        return NULL;
+
+    fp = Py_fopen(filename, "rb");
+    if (fp == NULL) {
+        return NULL;
+    }
+
+    value = PyMarshal_ReadShortFromFile(fp);
+    pos = ftell(fp);
+
+    fclose(fp);
+    if (PyErr_Occurred())
+        return NULL;
+    return Py_BuildValue("il", value, pos);
