+      time_based_(time_based),
+      rotate_at_(rotate_at),
+      origin_(uv_hrtime()) {
+  MakeWeak();
+  external_memory_ = spare_->GetMemorySize();
+  env->external_memory_accounter()->Increase(env->isolate(), external_memory_);
