+    Local<Value> argv[] = {hint_value};
+    Local<Value> ret;
+    if (!ctx->psk_callback_.Get(env->isolate())
+             ->Call(env->context(), ctx->object(), 1, argv)
+             .ToLocal(&ret)) {
+      ctx->ReportCallbackError(ssl, &try_catch);
+      return 0;
+    }
