+    Local<Value> key_val;
+    if (!obj->Get(env->context(),
+                  FIXED_ONE_BYTE_STRING(env->isolate(), "identity"))
+             .ToLocal(&id_val) ||
+        !obj->Get(env->context(), FIXED_ONE_BYTE_STRING(env->isolate(), "key"))
+             .ToLocal(&key_val)) {
+      ctx->ReportCallbackError(ssl, &try_catch);
+      return 0;
+    }
+    if (!id_val->IsString() || !key_val->IsArrayBufferView()) {
