+  split[addr2]++;
+  CHECK_EQ(split.size(), 2);
+
+  // PeerMap is the one that treats them as the peer they are.
+  SocketAddress::PeerMap<size_t> map;
+  map[addr1]++;
+  map[addr2]++;
+  CHECK_EQ(map.size(), 1);
