+  const client = connect('::1', endpoint.address.port, {
+    servername: 'agent1', ca: [ca],
+  });
+  await client.opened;
+
+  await client.close();
+  await endpoint.close();
+}
+
+// An explicit bindHost is still honoured.
+{
+  const endpoint = listen(() => {}, { cert, key, host: '::1', port: 0 });
+
