+  const endpoint = listen(() => {}, {
+    cert, key, host: '127.0.0.1', port: 0,
+  });
+  const client = connect('127.0.0.1', endpoint.address.port, {
+    servername: 'agent1', ca: [ca],
+  });
+  return { endpoint, client };
