+{
+  const { endpoint, client } = newClient();
+  client.destroy();
+
+  const result = await outcome(client.opened);
+  if (result === 'pending') assert.fail('opened must not hang after destroy()');
+  assert.strictEqual(result.code, 'ERR_INVALID_STATE');
