+  for (const [servername, expected] of [
+    ['agent1', 'CN=agent1'],            // An options bag.
+    ['localhost', 'CN=localhost'],      // A prepared context.
+  ]) {
+    const client = connect('127.0.0.1', endpoint.address.port, {
+      rejectUnauthorized: false, servername,
