+  for (let i = 0; i < 12; i++) {
+    const client = connect('127.0.0.1', endpoint.address.port, {
+      rejectUnauthorized: false, servername: `host-${i}.example`,
+    });
+    await client.opened;
+    assert.strictEqual(servedCommonName(client), 'CN=localhost');
+    globalThis.gc?.();
+    await client.close();
+  }
