+  for (const [returned, code] of [
+    [clientContext, 'ERR_INVALID_ARG_VALUE'],  // Built for a client.
+    ['a string', 'ERR_INVALID_ARG_TYPE'],
+    [42, 'ERR_INVALID_ARG_TYPE'],
