+    const endpoint = listen((session) => {
+      session.onerror = (err) => failed.resolve(err);
+    }, {
+      cert: agent1Cert,
+      key: agent1Key,
+      host: '127.0.0.1',
+      port: 0,
+      sni: () => returned,
+    });
+
+    const client = connect('127.0.0.1', endpoint.address.port, {
+      rejectUnauthorized: false, servername: 'anything',
+    });
