+    secureContext: prepared,
+    host: '127.0.0.1',
+    port: 0,
+    sni: { 'late.example': identity },
+  }), { code: 'ERR_INVALID_ARG_VALUE' });
+
+  // And it means nothing on a client.
+  assert.throws(() => createSecureContext({
+    sni: { 'a.example': identity },
+  }), { code: 'ERR_INVALID_ARG_VALUE' });
