+  const first = listen(() => {}, {
+    cert, key, host: HOST, port: 0, reusePort: true,
+  });
+  const port = first.address.port;
+
+  const second = listen(() => {}, {
+    cert, key, host: HOST, port, reusePort: true,
+  });
+  assert.strictEqual(second.address.port, port);
