+{
+  const bad = {
+    reusePort: ['yes', 1, null],
+    udpReceiveBufferSize: [0, -1, 1.5, '65536'],
+    udpSendBufferSize: [0, -1, 1.5, '65536'],
+    udpTTL: [0, 256, -1, 1.5, '64'],
