+int
+_PyBuiltin_InitPythonFunctions(PyObject *dict)
+{
+    if (PyImport_ImportFrozenModule("_pybuiltins") <= 0) {
+        if (!PyErr_Occurred()) {
+            PyErr_SetString(PyExc_ImportError,
+                            "frozen module _pybuiltins not found");
