+  const options = { format };
+  if (format === 'pem' || format === 'der') {
+    options.type = type === 'private' ? 'pkcs8' : 'spki';
+  }
+  let run;
+  if (operation === 'export') {
+    run = () => key.export(options);
+  } else {
+    const input = { ...options, key: key.export(options) };
+    if (format.startsWith('raw-')) {
