+  const auto name_field =
+      is_akp ? env->jwk_alg_string() : env->jwk_crv_string();
+  const auto public_field =
+      is_akp ? env->jwk_pub_string() : env->jwk_x_string();
+  const auto private_field =
+      is_akp ? env->jwk_priv_string() : env->jwk_d_string();
