+
+function array(items) {
+  const out = head(4, items.length);
+  for (const item of items) out.push(...item);
+  return out;
+}
+
+function map(entries) {
+  const out = head(5, entries.length);
+  for (const { 0: key, 1: value } of entries) out.push(...key, ...value);
+  return out;
