+
+void ProcessTimeoutWatchdog::OnEnvironmentStopping() {
+  uv_mutex_lock(&state_->mutex);
+  // The phase is only kFired here if the event loop stopped right as the
+  // deadline was reached, a race that tests cannot reproduce reliably.
+  if (state_->phase == State::Phase::kArmed ||
+      state_->phase == State::Phase::kFired) {  // LCOV_EXCL_LINE
+    state_->phase = State::Phase::kStopping;
+    uv_cond_signal(&state_->cond);
+  }
