+  spawnSyncAndAssert(process.execPath, [
+    '--process-timeout=10m',
+    __filename,
+    'child',
+  ], {
+    stderr: '',
+  });
+
+  testActivationRequestIsIgnored().then(common.mustCall());
+  return;
+}
