+    const start = process.hrtime.bigint();
+    const child = spawnSync(process.execPath, [
+      `--process-timeout=${timeout}ms`,
+      '-e',
+      `const { writeSync } = require('fs');\n${script}`,
+    ], { encoding: 'utf8' });
+    const elapsed = Number(process.hrtime.bigint() - start) / 1e6;
