+    assert.match(child.stderr, new RegExp(
+      `^\\(node:\\d+\\) Process timed out after ${timeout}ms \\(--process-timeout\\)\\. ` +
+      'Exiting with code 124\\.$', 'm'));
+    return child.stderr;
+  }
+}
