+  assert.match(stderr, /^Resources keeping the event loop alive:$/m);
+  assert.match(stderr, /^ {4}TCPServerWrap \(listening on \S+:\d+[,)]/m);
+  assert.match(stderr, /^ {4}Timeout \(next due in \d+ms\)$/m);
+}
