+    size_t begin = 0;
+    while (begin <= value.size()) {
+      size_t end = value.find(',', begin);
+      if (end == std::string::npos) end = value.size();
+      if (end > begin) patterns.emplace_back(value.substr(begin, end - begin));
+      begin = end + 1;
+    }
+  }
+  return patterns;
