+    lowest: 1000n,
+    highest: 3_600_000_000_000n,
+    figures: 2n,
+    countsLength: 3456n,
+  });
+
+  assert.deepStrictEqual(getLayout(monitorEventLoopDelay({
+    samplePerIteration,
+    lowest: 1_000_000n,
+    highest: 60_000_000_000n,
+    figures: 1,
+  })), {
+    lowest: 1_000_000n,
+    highest: 60_000_000_000n,
+    figures: 1n,
+    countsLength: 224n,
+  });
+
+  assert.deepStrictEqual(getLayout(monitorEventLoopDelay({
+    samplePerIteration,
+    lowest: 1_000_000,
+  })), {
+    lowest: 1_000_000n,
+    highest: kMaxInt64,
+    figures: 3n,
+    countsLength: 35840n,
