+  // resolution is roughly 99 days after enable().
+  assert.strictEqual(histogram.count, 0);
+  assert.strictEqual(histogram.exceeds, 0);
+});
+
+(function wait() {
+  if (control.count >= 10) {
+    done();
+  } else {
+    setTimeout(wait, 2);
+  }
+})();

