+            return Ok(Err(e));
+        }
+        self.1.try_write_to_parts(sink)
+    }
+    #[inline]
+    fn writeable_length_hint(&self) -> crate::LengthHint {
+        self.0.writeable_length_hint() + self.1.writeable_length_hint()
+    }
+}
+
+impl<A, B> fmt::Display for Concat<A, B>
