+    assert.strictEqual(connection.remoteAddress, '127.0.0.1');
+    assert.deepStrictEqual(connection.autoSelectFamilyAttemptedAddresses,
+                           [`127.0.0.1:${port}`, `${secondAddress}:${port}`]);
+  }));
