+    {prefix "noargs0", _PyCFunction_CAST(zero), METH_NOARGS},               \
+    {prefix "noargs1", _PyCFunction_CAST(one), METH_NOARGS},                \
+    {prefix "noargs2", _PyCFunction_CAST(two), METH_NOARGS},                \
