+    {prefix "varargs1", _PyCFunction_CAST(one), METH_VARARGS},              \
+    {prefix "varargs2", _PyCFunction_CAST(two), METH_VARARGS},              \
+    {prefix "varargs3", _PyCFunction_CAST(three), METH_VARARGS},            \
+                                                                            \
+    {prefix "kwargs0", _PyCFunction_CAST(zero),                             \
