+  for (int i = 0; i < scope_count; ++i) {
+    DebugScriptScope scope = DebugScriptScope::FromIndex(info, i);
+    if (scope.scope_type() == scope_type &&
+        scope.start_position() == start_position &&
+        scope.end_position() == end_position) {
