+        "EVENT_{}",
+        callback_name
+          .strip_prefix("on_")
+          .unwrap_or(&callback_name)
+          .to_uppercase()
+      );
+      let active_const = format_ident!("CALLBACK_ACTIVE_{}", callback_name.to_uppercase());
