+impl Parser {
+  /// Creates a new parser
+  pub fn new() -> Parser {
+    let mut events = Box::new([0u8; 65536]);
+    let events_ptr = events.as_mut_ptr();
+    mem::forget(events);
+
+    Parser {
+      // User writable
+      #[cfg(not(target_family = "wasm"))]
+      context: ptr::null_mut(),
+      max_start_line_length: 8192,
+      max_header_length: 8192,
+      max_body_payload: 0,
+      autodetect: true,
+      is_request: false,
+      suspend_after_headers: false,
+      manage_unconsumed: false,
+      continue_without_data: false,
+      is_connect: false,
+      skip_body: false,
+      debug: false,
+      // Generic state
+      parsed: 0,
+      position: 0,
+      state: STATE_START,
+      paused: false,
+      error_code: ERROR_NONE,
+      // Current message flags
+      content_length: 0,
+      chunk_size: 0,
+      remaining_content_length: 0,
+      remaining_chunk_size: 0,
+      status: 0,
+      method: 0,
+      has_content_length: false,
+      has_transfer_encoding: false,
+      has_chunked_transfer_encoding: false,
+      has_connection_close: false,
+      has_connection_upgrade: false,
+      has_upgrade: false,
+      has_trailers: false,
+      // Callbacks handling
+      active_callbacks: 0,
+      active_events: 0,
+      #[cfg(not(target_family = "wasm"))]
+      callbacks: ParserCallbacks::new(),
+      // WASM Specific
+      #[cfg(target_family = "wasm")]
+      ptr: ptr::null_mut(),
