+#[inline(always)]
+pub fn ensure_valid_line(data: &[u8], cr: usize, available: usize) -> MatchResult {
+  if cr + 1 == available {
+    MatchResult::Suspend
+  } else if data[cr + 1] != b'\n' {
+    MatchResult::Stop
+  } else {
+    MatchResult::Continue
+  }
+}
